fn rpc_data_column_received(
    &mut self,
    sync_request_id: SyncRequestId,
    peer_id: PeerId,
    data_column: Option<Arc<DataColumnSidecar<T::EthSpec>>>,
    seen_timestamp: Duration,
) {
    match sync_request_id {
        SyncRequestId::DataColumnsByRoot(req_id) => {
